import{_ as s,o as e,c as n,a6 as i}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"判断ガイド: インターフェースを作るべきか","description":"","frontmatter":{"title":"判断ガイド: インターフェースを作るべきか","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"根拠: ポリモーフィズム、DIP、ISP、YAGNI 作るシグナル: 実装が既に2つ(または2つ目が今期の計画にある)/モック無しでテストが書けない/#include連鎖がビルドを苦しめている境界(前方宣言では足りない場合)"}},"headers":[],"relativePath":"design/decisions/create-interface.md","filePath":"design/decisions/create-interface.md"}'),t={name:"design/decisions/create-interface.md"};function l(r,a,o,d,c,p){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="判断ガイド-インターフェースを作るべきか" tabindex="-1">判断ガイド: インターフェースを作るべきか <a class="header-anchor" href="#判断ガイド-インターフェースを作るべきか" aria-label="Permalink to &quot;判断ガイド: インターフェースを作るべきか&quot;">​</a></h1><h2 id="判断フロー" tabindex="-1">判断フロー <a class="header-anchor" href="#判断フロー" aria-label="Permalink to &quot;判断フロー&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. 実装は今いくつある? 2つ目は「確定した予定」か?</span></span>
<span class="line"><span>    → 1つで予定も曖昧 ──&gt; 作らない(具象クラスを直接使う)…ただしQ2へ</span></span>
<span class="line"><span>Q2. テストで差し替えたい依存か?(I/O・時間・乱数・ネットワーク・課金)</span></span>
<span class="line"><span>    → はい ──&gt; 作る(実装1つでもテスト用フェイクが2つ目の実装)</span></span>
<span class="line"><span>    → いいえ ──&gt; Q3へ</span></span>
<span class="line"><span>Q3. 呼び出し側と実装側を、別々に変更・ビルド・配布したい境界か?</span></span>
<span class="line"><span>   (モジュール境界、チーム境界、DLL境界、エンジン非依存層)</span></span>
<span class="line"><span>    → はい ──&gt; 作る</span></span>
<span class="line"><span>    → いいえ ──&gt; 作らない。必要になった日に抽出すればよい(安い作業)</span></span></code></pre></div><p>根拠: <a href="/study/design/foundations/polymorphism-interface.html">ポリモーフィズム</a>、<a href="/study/design/solid/dip.html">DIP</a>、<a href="/study/design/solid/isp.html">ISP</a>、<a href="/study/design/foundations/yagni-kiss-dry.html">YAGNI</a></p><h2 id="判断材料" tabindex="-1">判断材料 <a class="header-anchor" href="#判断材料" aria-label="Permalink to &quot;判断材料&quot;">​</a></h2><ul><li><strong>作るシグナル</strong>: 実装が既に2つ(または2つ目が今期の計画にある)/モック無しでテストが書けない/<code>#include</code>連鎖がビルドを苦しめている境界(<a href="/study/runtime/cpp-internals/translation-units-and-headers.html">前方宣言では足りない場合</a>)</li><li><strong>作らないシグナル</strong>: 「いつか差し替えるかも」以外の理由が言えない/インターフェース名が <code>IEnemyManager</code> のように実装名の頭にIを付けただけ(抽象の語彙が生まれていない → <a href="/study/design/solid/dip.html">DIPの「抽象の所有」</a>)</li></ul><h2 id="例外" tabindex="-1">例外 <a class="header-anchor" href="#例外" aria-label="Permalink to &quot;例外&quot;">​</a></h2><ul><li><strong>公開API・プラグイン境界</strong>: 実装が1つでも最初からインターフェースにする(外部に具象を晒すと後から変えられない——可逆性の原則の例外側)</li><li><strong>ホットループの内側</strong>: テスト差し替えのためでも、毎フレーム数万回呼ぶ箇所に仮想関数を挟むのは要計測(→ <a href="/study/design/decisions/cpp-choices.html">テンプレートか仮想関数か</a>)</li></ul><h2 id="トレードオフ" tabindex="-1">トレードオフ <a class="header-anchor" href="#トレードオフ" aria-label="Permalink to &quot;トレードオフ&quot;">​</a></h2><ul><li>得: 差し替え・テスト・ビルド分離・依存方向の制御</li><li>失: 間接1段(実行時+読解時)、「定義へ移動」がインターフェースに飛ぶ迷路、ファイル数、<strong>抽象の設計責任</strong>(下手な抽象は具象より害 → 実装1つの段階では良い抽象を設計する材料が足りない、が「後で抽出」推奨の本当の理由)</li></ul><h2 id="実践のコツ" tabindex="-1">実践のコツ <a class="header-anchor" href="#実践のコツ" aria-label="Permalink to &quot;実践のコツ&quot;">​</a></h2><ul><li>後からの抽出は安い: 具象クラスの利用箇所を「その関数シグネチャのまま」インターフェースに置き換えるのはIDE支援でほぼ機械作業。<strong>「後で抽出できる形」=具象のpublic APIを小さく保つ</strong>ことが、前倒しの抽象より価値がある</li><li>作るときは<a href="/study/design/solid/isp.html">ISP</a>: 呼び出し側が使う分だけの小さい顔で</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>実装が1つでもインターフェースを作る2条件は?</li><li>「頭にIを付けただけの抽象」の何が問題ですか。</li><li>「後で抽出」が安い前提条件は?</li></ol><hr><p>前: <a href="/study/design/decisions/split-class.html">クラスを分けるべきか</a> | <a href="/study/design/decisions/">カテゴリ目次</a> | 次: <a href="/study/design/decisions/inheritance-or-composition.html">継承かコンポジションか</a></p>`,16)])])}const g=s(t,[["render",l]]);export{u as __pageData,g as default};
